<?php
// Round 4 (builder-E): the "Use your own AI" JSON import. Included by tests/round4_tests.php. All people, banks and numbers are made up.
$jx = fn(array $d) => json_encode($d, JSON_UNESCAPED_UNICODE);
$jBuild = function (int $uid, array $doc, array $notes = []) { return import_json_build($doc, $notes, import_json_context($uid), 'test.json'); };
$jIssues = fn(array $stmt, string $code, ?int $n = null) => array_values(array_filter($stmt['json']['issues'], fn($x) => $x['code'] === $code && ($n === null || $x['n'] === $n)));
$jRow = fn(array $stmt, int $n) => array_values(array_filter($stmt['rows'], fn($r) => $r['n'] === $n))[0] ?? null;
$jTx = fn(array $o) => $o + ['date' => '2026-10-02', 'type' => 'expense', 'amount' => '100.00', 'account' => 'Test Bank', 'payee' => 'Shop'];
$jDoc = fn(array $tx, array $more = []) => $more + ['version' => 1, 'accounts' => [['name' => 'Test Bank', 'type' => 'bank'], ['name' => 'Test Cash', 'type' => 'cash']], 'transactions' => $tx];

section('R4 JSON: decoding keeps money as text and repairs what AIs get wrong');
$notes = []; $d = import_json_decode("Sure! Here is your file:\n```json\n{\"version\": 1, \"transactions\": [{\"amount\": 19.99, \"big\": 12345678901234567890, \"neg\": -0.1, \"exp\": 1.5E+3, \"ok\": true, \"n\": null,},],}\n```\nLet me know!", $notes);
eq($d['transactions'][0]['amount'], '19.99', '19.99 stays the text "19.99" (never a float)'); eq($d['transactions'][0]['big'], '12345678901234567890', 'a number beyond 64 bits survives as text'); eq($d['transactions'][0]['neg'], '-0.1', 'negative decimals survive'); eq($d['transactions'][0]['exp'], '1.5E+3', 'exponent form is kept (and handled by the money parser)'); eq($d['transactions'][0]['ok'], true, 'booleans stay booleans'); eq($d['version'], '1', 'version is text too');
check('repairs are reported', in_array('The code fence around the JSON was removed.', $notes, true) && (bool) array_filter($notes, fn($x) => str_contains($x, 'trailing comma')));
$notes = []; import_json_decode("\xEF\xBB\xBF  {\"a\": \"b\"} trailing words", $notes); check('BOM and text after the object are tolerated with a note', (bool) array_filter($notes, fn($x) => str_contains($x, 'around')));
foreach ([['{"a": 1', 'cut off'], ["{'a': 1}", 'single quotes'], ['{"a": [1, 2}', 'brackets do not match'], ['{"a": tru}', 'double quotes'], ['{"a": "x', 'cut off'], ['{"a": .5}', 'unexpected'], ['', 'Paste'], ['[1,2]', 'JSON object'], ['no json here', 'JSON object'], ['{"a": 1 // c' . "\n}", 'comments']] as [$bad, $needle]) { throws(fn() => import_json_decode($bad), $needle, 'bad JSON explained: ' . substr(str_replace("\n", ' ', $bad), 0, 24)); }
throws(fn() => import_json_decode("{\n  \"a\": 1,\n  \"b\": 'x'\n}"), 'Line 3', 'the error names the line'); throws(fn() => import_json_decode(str_repeat('[', 14) . str_repeat(']', 14)), 'JSON object', 'a bare array is refused'); throws(fn() => import_json_decode('{"a":' . str_repeat('{"a":', 14) . '1' . str_repeat('}', 15) . '}'), 'deep', 'nesting deeper than 10 is refused');
throws(fn() => import_json_decode(str_repeat('x', IMPORT_JSON_MAX_BYTES + 1)), 'too large', 'oversized text is refused'); $win = import_json_decode('{"a": "caf' . "\xE9" . '"}'); eq($win['a'], 'café', 'Windows-1252 text is converted');

section('R4 JSON: money, dates and hints are parsed with integer arithmetic');
$mm = fn(string $v, string $dec = '', string $th = '') => (imj_money($v, $dec, $th)['minor'] ?? null);
eq($mm('1,520.50'), 152050, '1,520.50'); eq($mm('₹ 1,23,456.5'), 12345650, 'Indian grouping with a rupee sign'); eq($mm('19.99'), 1999, '19.99 has no float error'); eq($mm('0.1'), 10, '0.1'); eq($mm('1.234,56', ',', '.'), 123456, 'decimal comma with dot thousands'); eq($mm('1.234,56'), 123456, '... detected without a hint'); eq($mm('1,234'), 123400, '1,234 is a thousands comma'); eq($mm('12,5'), 1250, '12,5 is a decimal comma');
eq($mm('1.5E+3'), 150000, 'scientific notation'); eq($mm('1.005'), 101, 'a third decimal rounds half up'); eq($mm('999999999999.99'), 99999999999999, 'a huge amount does not overflow'); eq($mm('abc'), null, 'text is not an amount'); eq($mm('1.2.3.4x'), null, 'junk is not an amount'); eq($mm("12'345.60"), 1234560, "Swiss grouping"); eq($mm('Rs. 5'), 500, 'Rs. prefix');
check('(250) is negative and 250 Dr is a debit', imj_money('(250)')['neg'] === true && imj_money('250 Dr')['crdr'] === 'dr' && imj_money('-12')['neg'] === true && imj_money('12-')['neg'] === true);
eq(imj_money('1.5000')['decimals'], 1, 'trailing zeros are not extra decimals'); eq(imj_money('1.256')['decimals'], 3, 'real third decimal counted');
eq(imj_date('2026-10-01')['date'], '2026-10-01', 'ISO'); eq(imj_date('01/10/2026')['ambiguous'], true, '01/10/2026 is ambiguous'); eq(imj_date('13/10/2026')['date'], '2026-10-13', 'day first when the first number is above 12'); eq(imj_date('10/13/2026')['date'], '2026-10-13', 'month first when the second is above 12');
eq(imj_date('01/10/2026', 'mdy')['date'], '2026-01-10', 'month-first hint'); eq(imj_date('01/10/2026', 'dmy')['ambiguous'], false, 'a hint removes the ambiguity'); eq(imj_date('1 Oct 2026')['date'], '2026-10-01', 'd Mon yyyy'); eq(imj_date('October 1, 2026')['date'], '2026-10-01', 'Month d, yyyy'); eq(imj_date('1st Oct 2026')['date'], '2026-10-01', 'ordinals'); eq(imj_date('20261001')['date'], '2026-10-01', 'compact'); eq(imj_date('31/02/2026'), null, 'an impossible date is refused');
eq(imj_date('2026-10-01T10:15:00+05:30')['time'], '10:15:00', 'a +05:30 timestamp stays IST'); eq(imj_date('2026-10-01T23:00:00Z')['date'], '2026-10-02', 'a UTC timestamp is converted to India time (next day)'); eq(imj_date('2026-10-01 10:00:00', null, 'UTC')['time'], '15:30:00', 'the file timezone applies to timestamps without an offset');
eq(imj_date('01/10/2026 02:30 PM')['time'], '14:30:00', 'am/pm'); eq(imj_time('9.05'), '09:05:00', 'time with a dot'); eq(imj_time('25:00'), null, 'invalid time');
eq(imj_order_hint('DD/MM/YYYY'), 'dmy', 'hint dd/mm/yyyy'); eq(imj_order_hint('mm-dd-yyyy'), 'mdy', 'hint mm-dd-yyyy'); eq(imj_order_hint('d mmm yyyy'), 'dmy', 'hint d mmm yyyy'); eq(imj_order_hint('auto'), null, 'auto');

section('R4 JSON: a clean file is imported exactly, with transfers, categories, bills, goals, budgets and undo');
$JU = create_user('rj1@x.test', 'Json One', 'password-12345'); $_SESSION['uid'] = $JU; unset($GLOBALS['__user']); $jsnap = load_snapshot($JU); $mainAcc = (int) $jsnap['accounts'][0]['id']; $nBefore = (int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$JU]);
run('UPDATE {accounts} SET opening_date=? WHERE user_id=?', ['2026-01-01', $JU]); $jsnap = load_snapshot($JU); $ex = import_json_example(); $tokE = import_json_handle_text($JU, $jx($ex), 'example.json'); $pvE = import_load_preview($JU, $tokE); $stE = $pvE['stmt'];
eq($stE['source'], 'json', 'the example file is recognised as JSON'); eq(count($stE['rows']), 4, 'four example rows'); eq($stE['json']['counts']['error'], 0, 'the shipped example has no errors'); eq($stE['json']['counts']['warning'], 0, 'and no warnings'); eq($stE['json']['issues_total'], 0, 'no issues at all');
check('the shipped prompt, schema and example agree: the example validates', $stE['json']['declared']['income'] === 8500000 && $stE['json']['declared']['expense'] === 152050);
eq(array_column($stE['rows'], 'amount'), [8500000, 152050, 500000, 25000], 'amounts are exact paise'); eq(array_column($stE['rows'], 'xt'), ['income', 'expense', 'transfer', 'refund'], 'types'); eq($stE['rows'][2]['to_account'], 'Cash', 'the transfer has a destination'); eq($stE['rows'][1]['notes'], 'Weekly shopping · Tags: family', 'description beside a payee and tags go to the notes');
$ch = import_default_choices($jsnap, $stE); $ag = import_account_groups($stE); eq(array_column($ag, 'name'), ['Example Savings', 'Cash'], 'both the source and the destination of a transfer are accounts to map');
$cash0 = (int) array_column($jsnap['accounts'], 'balance', 'name')['Cash']; $ch['mode'] = 'reflect'; $res = import_commit($JU, $tokE, $ch); eq($res['imported'], 4, 'four transactions were written'); eq($res['accounts_created'], 1, 'one new account (Cash already exists and is matched by name)'); $im = (int) $res['import_id'];
$rowsDb = all('SELECT t.*, a.name AS an FROM {transactions} t LEFT JOIN {accounts} a ON a.id=t.account_id WHERE t.import_id=? AND t.type<>? ORDER BY t.date,t.id', [$im, 'adjustment']);
eq(array_column($rowsDb, 'type'), ['income', 'expense', 'transfer', 'refund'], 'stored types'); eq(array_map('intval', array_column($rowsDb, 'amount')), [8500000, 152050, 500000, 25000], 'stored amounts'); check('the transfer has to_account_id set and a category of NULL', $rowsDb[2]['to_account_id'] !== null && $rowsDb[2]['category_id'] === null && (int) $rowsDb[2]['to_account_id'] !== (int) $rowsDb[2]['account_id']);
eq($rowsDb[0]['source'], 'json', 'source json'); eq($rowsDb[1]['source_ref'], 'UPI0002', 'the reference is the dedupe key'); eq($rowsDb[1]['notes'], 'Weekly shopping · Tags: family', 'notes stored'); eq($rowsDb[0]['txn_time'], '09:30:00', 'time stored');
$sav = one('SELECT * FROM {accounts} WHERE user_id=? AND name=?', [$JU, 'Example Savings']); eq($sav['type'], 'bank', 'account type from the file');
eq((int) $sav['opening_balance'], 5000000, 'opening_balances sets the new account\'s opening balance'); $sn2 = load_snapshot($JU); $balOf = fn($name) => (int) array_column($sn2['accounts'], 'balance', 'name')[$name];
eq($balOf('Example Savings'), 5000000 + 8500000 - 152050 - 500000 + 25000, 'the savings balance is opening + income - expense - transfer + refund (matches the file\'s last balance_after 128729.50 + 0)'); eq($balOf('Cash'), $cash0 + 500000, 'the transfer moved ₹5,000 into your existing Cash account'); eq((int) $rowsDb[2]['to_account_id'], (int) one('SELECT id FROM {accounts} WHERE user_id=? AND name=?', [$JU, 'Cash'])['id'], 'to_account_id is the matched Cash account');
eq(count(all('SELECT id FROM {bills} WHERE user_id=?', [$JU])), 1, 'the bill was created'); eq(count(all('SELECT id FROM {goals} WHERE user_id=? AND name=?', [$JU, 'Emergency fund'])), 1, 'the goal was created'); $bc = one('SELECT c.id FROM {categories} c WHERE c.user_id=? AND c.name=?', [$JU, 'Groceries']); eq((int) val('SELECT amount FROM {budgets} WHERE user_id=? AND category_id=?', [$JU, $bc['id']]), 1200000, 'the budget was set');
$sumE = json_decode((string) val('SELECT summary FROM {imports} WHERE id=?', [$im]), true); check('the summary remembers what undo needs', !empty($sumE['x_bills']) && !empty($sumE['x_goals']) && !empty($sumE['x_budgets']));
$tok2 = import_json_handle_text($JU, $jx($ex), 'again.json'); $st2 = import_load_preview($JU, $tok2)['stmt']; $pl2 = import_plan($JU, $st2, import_default_choices(load_snapshot($JU), $st2)); eq(count(array_filter($pl2, fn($p) => $p['dup'])), 4, 'importing the same file again: every row is recognised as already imported');
$n = import_remove($JU, $im); check('undo deletes the rows, the accounts, the bill, the goal and puts the budget back', $n >= 4 && !one('SELECT id FROM {accounts} WHERE user_id=? AND name=?', [$JU, 'Example Savings']) && !all('SELECT id FROM {bills} WHERE user_id=?', [$JU]) && !all('SELECT id FROM {goals} WHERE user_id=? AND name=?', [$JU, 'Emergency fund']) && val('SELECT amount FROM {budgets} WHERE user_id=? AND category_id=?', [$JU, $bc['id']]) === null);
eq((int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$JU]), $nBefore, 'the ledger is exactly as before');

section('R4 JSON: sanity checks (errors block a row, warnings allow it), each with a row reference');
$JV = create_user('rj2@x.test', 'Json Two', 'password-12345'); load_demo_data($JV); $_SESSION['uid'] = $JV; unset($GLOBALS['__user']);
$st = $jBuild($JV, $jDoc([$jTx(['amount' => '0']), $jTx(['amount' => '']), $jTx(['amount' => 'twelve']), $jTx(['date' => '']), $jTx(['date' => '31/02/2026']), $jTx(['date' => '1990-01-01']), $jTx(['type' => '']), $jTx(['account' => 'Unknown Co', 'type' => 'transfer', 'to_account' => 'Unknown Co']), $jTx(['type' => 'transfer', 'to_account' => 'Test Cash', 'account' => 'Test Cash']), $jTx(['amount' => '99999999999999'])]));
foreach ([[1, 'amount0'], [2, 'amount'], [3, 'amount'], [4, 'date'], [5, 'date'], [6, 'date_range'], [7, 'type'], [8, 'transfer'], [9, 'transfer'], [10, 'amount_big']] as [$n, $code]) { $i = $jIssues($st, $code, $n); check("row $n: $code is an error that blocks the row", $i && $i[0]['sev'] === 'error' && $jRow($st, $n)['blocked'] === true); }
eq($st['json']['counts']['error'] >= 10, true, 'the summary counts the errors');
$st = $jBuild($JV, $jDoc([$jTx(['type' => 'income', 'amount' => '-500']), $jTx(['type' => 'expense', 'amount' => '-500']), $jTx(['amount' => '12.3456']), $jTx(['date' => '2031-01-01']), $jTx(['date' => '2026-10-24']), $jTx(['date' => '01/02/2026']), $jTx(['type' => 'expense', 'category' => 'Salary']), $jTx(['type' => 'income', 'category' => 'Groceries']), $jTx(['currency' => 'USD', 'amount' => '10'])]));
$w = fn($n, $c) => $jIssues($st, $c, $n);
check('income with a negative amount: warning + flip option', $w(1, 'sign_type') && $w(1, 'sign_type')[0]['sev'] === 'warning' && in_array('flip', array_column($w(1, 'sign_type')[0]['fix'], 'a'), true) && $jRow($st, 1)['amount'] === 50000 && !$jRow($st, 1)['blocked']);
check('expense with a negative amount: warning, absolute value used', (bool) $w(2, 'sign_type') && $jRow($st, 2)['amount'] === 50000); check('too many decimals: warning, rounded', $w(3, 'decimals') && $jRow($st, 3)['amount'] === 1235 && $w(3, 'decimals')[0]['sev'] === 'warning');
check('a date more than a year ahead is an error', (bool) $jIssues($st, 'date_range', 4)); check('a date a few days ahead is only past tolerance when beyond 3 days (2026-10-24 is within)', !$jIssues($st, 'date_future', 5)); check('ambiguous 01/02/2026 is a warning with a swap option', $w(6, 'date_amb') && in_array('swapdm', array_column($w(6, 'date_amb')[0]['fix'], 'a'), true));
check('an income category on an expense is flagged', (bool) $w(7, 'cat_type')); check('an expense category on income is flagged', (bool) $w(8, 'cat_type')); check('another currency without exchange_rate is an error', $jIssues($st, 'currency', 9) && $jRow($st, 9)['blocked']);
$st = $jBuild($JV, $jDoc([$jTx(['currency' => 'USD', 'amount' => '10.00', 'exchange_rate' => '83.25'])])); eq($jRow($st, 1)['amount'], 83250, 'with exchange_rate the amount is converted with integer maths (10.00 USD x 83.25 = ₹832.50)'); check('and the original is kept in the notes', str_contains($jRow($st, 1)['notes'], 'USD 10.00 at 83.25'));
$st = $jBuild($JV, $jDoc([$jTx(['date' => '2026-12-25'])])); check('a date after the tolerance is a warning', (bool) $jIssues($st, 'date_future', 1) && !$jRow($st, 1)['blocked']); $st = $jBuild($JV, $jDoc([$jTx(['date' => '2026-12-25', 'status' => 'planned'])])); check('a planned future row is fine', !$jIssues($st, 'date_future', 1));
$st = $jBuild($JV, $jDoc([$jTx(['currency' => 'EUR', 'exchange_rate' => '90']), $jTx(['currency' => 'INR'])], ['currency' => 'INR'])); check('a row currency that differs from the file currency is flagged', (bool) $jIssues($st, 'currency_mix', 1));

section('R4 JSON: duplicates inside the file and against what you already have');
$exTx = one('SELECT * FROM {transactions} WHERE user_id=? AND type=? AND status=? ORDER BY id LIMIT 1', [$JV, 'expense', 'completed']); $exDate = $exTx['date']; $exAmt = number_format($exTx['amount'] / 100, 2, '.', '');
$st = $jBuild($JV, $jDoc([$jTx(['ref' => 'R1', 'amount' => '10.00']), $jTx(['ref' => 'R1', 'amount' => '10.00']), $jTx(['amount' => '55.55', 'payee' => 'Twice']), $jTx(['amount' => '55.55', 'payee' => 'Twice']), $jTx(['ref' => 'R2', 'amount' => '77.00', 'payee' => 'Samey']), $jTx(['ref' => 'R3', 'amount' => '77.00', 'payee' => 'Samey']), $jTx(['date' => $exDate, 'amount' => $exAmt, 'payee' => '', 'description' => ''])]));
$d1 = $jIssues($st, 'dup_ref', 2); check('the same reference twice is an error on the second row with a "keep it" option', $d1 && $d1[0]['sev'] === 'error' && $jRow($st, 2)['blocked'] && in_array('keep', array_column($d1[0]['fix'], 'a'), true)); check('the first row is fine', !$jRow($st, 1)['blocked']);
check('identical rows without a reference: warning on the second', (bool) $jIssues($st, 'dup_same', 4) && !$jRow($st, 4)['blocked']); check('same date/amount/payee with different references: warning', (bool) $jIssues($st, 'dup_fuzzy', 6)); check('a row like one you already have (same amount, date, no payee) is flagged with its id', (bool) $jIssues($st, 'dup_existing', 7) && str_contains($jIssues($st, 'dup_existing', 7)[0]['msg'], '#' . $exTx['id']));
$refTx = one('SELECT id FROM {transactions} WHERE user_id=? AND type=? ORDER BY id LIMIT 1', [$JV, 'expense']); run('UPDATE {transactions} SET source=?, source_ref=? WHERE id=?', ['paytm', 'PTM-9999', $refTx['id']]); $amtRef = (int) val('SELECT amount FROM {transactions} WHERE id=?', [$refTx['id']]);
$st = $jBuild($JV, $jDoc([$jTx(['ref' => 'PTM-9999', 'amount' => number_format($amtRef / 100, 2, '.', '')])])); check('a reference that is already in the ledger (from another source) with the same amount is an error', (bool) $jIssues($st, 'dup_existing_ref', 1) && $jRow($st, 1)['blocked']);
$st = $jBuild($JV, $jDoc([$jTx(['ref' => 'PTM-9999', 'amount' => '1.00'])])); check('...but not when the amount differs', !$jIssues($st, 'dup_existing_ref', 1));

section('R4 JSON: running balance, declared totals and bulk patterns');
$st = $jBuild($JV, $jDoc([$jTx(['date' => '2026-10-01', 'type' => 'income', 'amount' => '1000.00', 'balance_after' => '1000.00']), $jTx(['date' => '2026-10-02', 'amount' => '100.00', 'balance_after' => '900.00']), $jTx(['date' => '2026-10-03', 'amount' => '50.00', 'balance_after' => '800.00']), $jTx(['date' => '2026-10-04', 'amount' => '10.00', 'balance_after' => '790.00'])]));
$bc = $jIssues($st, 'balance_chain'); eq(count($bc), 1, 'one break in the chain is found (row 3: 900-50 is 850, the file says 800)'); eq($bc[0]['n'], 3, 'at row 3'); check('the explanation gives expected and found', str_contains($bc[0]['msg'], '₹850') && str_contains($bc[0]['msg'], '₹800'));
$st = $jBuild($JV, $jDoc([$jTx(['date' => '2026-10-01', 'amount' => '33.33', 'balance_after' => '966.67']), $jTx(['date' => '2026-10-02', 'amount' => '10.00', 'balance_after' => '956.68'])], ['opening_balances' => ['Test Bank' => '1000.00']])); check('an off-by-one-paisa balance is reported as rounding drift', (bool) $jIssues($st, 'balance_drift', 2) && !$jIssues($st, 'balance_chain'));
$st = $jBuild($JV, $jDoc([$jTx(['date' => '2026-10-04', 'amount' => '10.00', 'balance_after' => '790.00']), $jTx(['date' => '2026-10-03', 'amount' => '50.00', 'balance_after' => '800.00']), $jTx(['date' => '2026-10-02', 'amount' => '100.00', 'balance_after' => '850.00']), $jTx(['date' => '2026-10-01', 'type' => 'income', 'amount' => '1000.00', 'balance_after' => '950.00'])]));
check('a newest-first statement is checked in the right direction (one break at most, not three)', count($jIssues($st, 'balance_chain')) <= 2);
$st = $jBuild($JV, $jDoc([$jTx(['type' => 'income', 'amount' => '500.00']), $jTx(['amount' => '120.00']), $jTx(['amount' => '30.00'])], ['declared_totals' => ['income' => '500.00', 'expense' => '150.00', 'count' => 3]])); eq($st['json']['counts']['warning'], 0, 'declared totals that match produce no warning');
$st = $jBuild($JV, $jDoc([$jTx(['type' => 'income', 'amount' => '500.00']), $jTx(['amount' => '120.00']), $jTx(['amount' => '30.00'])], ['declared_totals' => ['income' => '600.00', 'expense' => '150.00', 'count' => 4, 'by_account' => ['Test Bank' => ['income' => '500.00', 'expense' => '100.00', 'count' => 2]]]]));
check('declared income mismatch is explained with the difference', (bool) array_filter($jIssues($st, 'declared_income'), fn($x) => str_contains($x['msg'], '₹600') && str_contains($x['msg'], '₹500') && str_contains($x['msg'], '₹100'))); check('declared count and per-account mismatches are flagged', (bool) $jIssues($st, 'declared_count') && count($jIssues($st, 'declared_acc')) >= 2);
$many = []; for ($i = 0; $i < 30; $i++) { $many[] = $jTx(['date' => '2026-10-02', 'amount' => '500.00', 'payee' => 'Same Payee', 'ref' => 'S' . $i]); } $st = $jBuild($JV, $jDoc($many)); check('thirty identical lines are called suspicious', (bool) $jIssues($st, 'bulk_same'));
$tooMany = []; for ($i = 0; $i < IMPORT_JSON_MAX_ROWS + 1; $i++) { $tooMany[] = ['date' => '2026-10-02', 'amount' => '1']; } throws(fn() => $jBuild($JV, $jDoc($tooMany)), '5000', 'more than 5000 rows are refused'); throws(fn() => $jBuild($JV, ['version' => 1, 'transactions' => []]), 'no transactions', 'an empty file is refused'); throws(fn() => $jBuild($JV, ['version' => 2, 'transactions' => [['date' => '2026-10-01', 'amount' => '1']]]), 'version 2', 'another format version is refused'); throws(fn() => $jBuild($JV, ['version' => 1, 'transactions' => ['x' => 1]]), 'list', 'transactions must be a list');
$st = $jBuild($JV, $jDoc(['not an object', $jTx([])])); check('an entry that is not an object is reported and skipped', (bool) $jIssues($st, 'shape', 1) && count($st['rows']) === 1);
$st = $jBuild($JV, ['transactions' => [$jTx(['account' => 'Other Account'])], 'accounts' => [['name' => 'A'], ['name' => 'B']]]); check('an unlisted account gets one file-level warning; a missing version only a warning', (bool) $jIssues($st, 'acc_unlisted') && (bool) $jIssues($st, 'version'));
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-01', 'amount' => '5', 'type' => 'expense']], 'accounts' => [['name' => 'Only One']]]); eq($st['rows'][0]['account'], 'Only One', 'with a single declared account, rows without an account use it');
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-01', 'amount' => '5', 'type' => 'expense']]]); check('no account at all is an error', (bool) $jIssues($st, 'account', 1));
