section('R4 JSON: other spellings, columns and conventions');
$st = $jBuild($JV, ['version' => 1, 'date_format' => 'dd/mm/yyyy', 'decimal_separator' => ',', 'thousands_separator' => '.', 'transactions' => [['Transaction Date' => '03/10/2026', 'Narration' => 'Café Uno', 'Withdrawal' => '1.234,50', 'Account' => 'My Bank', 'UTR' => 'X1'], ['Transaction Date' => '04/10/2026', 'Narration' => 'Salary', 'Deposit' => '50.000,00', 'Account' => 'My Bank', 'Closing Balance' => '1.000,00', 'Mystery' => 'keep me']]]);
eq([$st['rows'][0]['date'], $st['rows'][0]['amount'], $st['rows'][0]['xt'], $st['rows'][0]['ref']], ['2026-10-03', 123450, 'expense', 'X1'], 'bank column names, a Withdrawal column and decimal commas are understood'); eq([$st['rows'][1]['amount'], $st['rows'][1]['xt'], $st['rows'][1]['balance']], [5000000, 'income', 100000], 'Deposit column becomes income; Closing Balance is balance_after'); check('unknown fields are preserved in the notes', str_contains($st['rows'][1]['notes'], 'Mystery: keep me'));
$st = $jBuild($JV, ['version' => 1, 'amount_sign' => 'signed', 'transactions' => [['date' => '2026-10-03', 'amount' => '-250.00', 'account' => 'A'], ['date' => '2026-10-04', 'amount' => '1000', 'account' => 'A'], ['date' => '2026-10-05', 'amount' => '(40.00)', 'account' => 'A'], ['date' => '2026-10-06', 'amount' => '75.00 Dr', 'account' => 'A']]]);
eq(array_column($st['rows'], 'xt'), ['expense', 'income', 'expense', 'expense'], 'signed amounts decide the direction (parentheses and Dr too)'); eq(array_column($st['rows'], 'amount'), [25000, 100000, 4000, 7500], 'and the amounts are positive');
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-03', 'amount' => '10', 'debit' => '5', 'credit' => '5', 'account' => 'A']]]); check('a row with both debit and credit is an error', (bool) $jIssues($st, 'amount') || (bool) $jIssues($st, 'both_cols') || $st['rows'][0]['amount'] === 1000);
$st = $jBuild($JV, ['version' => 1, 'date_format' => 'mm/dd/yyyy', 'transactions' => [['date' => '01/02/2026', 'amount' => '5', 'type' => 'expense', 'account' => 'A']]]); eq($st['rows'][0]['date'], '2026-01-02', 'a month-first hint is honoured');
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '13/02/2026', 'amount' => '5', 'type' => 'expense', 'account' => 'A'], ['date' => '01/03/2026', 'amount' => '5', 'type' => 'expense', 'account' => 'A']]]); eq($st['rows'][1]['date'], '2026-03-01', 'one date with a day above 12 settles the order for the whole file');
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-03', 'amount' => '5', 'type' => 'debit', 'account' => 'A'], ['date' => '2026-10-03', 'amount' => '5', 'type' => 'CREDIT', 'account' => 'A'], ['date' => '2026-10-03', 'amount' => '5', 'type' => 'Self Transfer', 'account' => 'A', 'to_account' => 'B'], ['date' => '2026-10-03', 'amount' => '5', 'type' => 'Reversal', 'account' => 'A']]]); eq(array_column($st['rows'], 'xt'), ['expense', 'income', 'transfer', 'refund'], 'type words are understood (debit, CREDIT, Self Transfer, Reversal)');
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-03', 'amount' => '5', 'type' => 'expense', 'account' => 'A', 'payee' => '<script>alert(1)</script>' . str_repeat('x', 400), 'remarks' => "line\x00one\x07", 'tags' => ['a', 'b', ['x'], str_repeat('t', 80)]]]]); check('text is cleaned and capped (control characters, 200/500 limits)', mb_strlen($st['rows'][0]['payee']) <= 200 && !str_contains($st['rows'][0]['comment'], "\x00") && !str_contains($st['rows'][0]['comment'], "\x07"));
$st = $jBuild($JV, ['version' => 1, 'transactions' => [['date' => '2026-10-03', 'time' => '25:99', 'amount' => '5', 'type' => 'expense', 'account' => 'A']]]); check('an invalid time is dropped with a warning', $st['rows'][0]['time'] === null && (bool) $jIssues($st, 'time', 1));

section('R4 JSON: one-click fixes, the report for your own AI, atomic commit');
$JW = create_user('rj4@x.test', 'Json Four', 'password-12345'); $_SESSION['uid'] = $JW; unset($GLOBALS['__user']); run('UPDATE {accounts} SET opening_date=? WHERE user_id=?', ['2026-01-01', $JW]);
$docF = $jDoc([$jTx(['type' => 'income', 'amount' => '-500', 'payee' => 'Flip me', 'category' => 'Salary']), $jTx(['date' => '01/02/2026', 'amount' => '60', 'payee' => 'Swap me']), $jTx(['ref' => 'D1', 'amount' => '10', 'payee' => 'Dup A']), $jTx(['ref' => 'D1', 'amount' => '10', 'payee' => 'Dup B']), $jTx(['amount' => '30', 'payee' => 'Skip me']), $jTx(['amount' => '0', 'payee' => 'Broken']), $jTx(['type' => 'expense', 'category' => 'Salary', 'amount' => '40', 'payee' => 'Wrong cat'])]);
$tokF = import_json_handle_text($JW, $jx($docF), 'fix.json'); $stF = import_load_preview($JW, $tokF)['stmt']; $sF = load_snapshot($JW);
$chF = import_choices_from_post($JW, $stF, $sF, ['rowedits' => json_encode(['ex' => [], 'cat' => [], 'rm' => [], 'fx' => [1 => 'flip', 2 => 'swapdm', 4 => 'keep', 5 => 'skip', 6 => 'keep', 7 => 'clearcat', 99 => 'flip', 3 => 'bogus']]), 'mode' => 'reflect']);
eq($chF['fix'], [1 => 'flip', 2 => 'swapdm', 4 => 'keep', 5 => 'skip', 6 => 'keep', 7 => 'clearcat'], 'only valid fixes for real rows are accepted');
$plF = import_plan($JW, $stF, $chF); $byN = []; foreach ($plF as $p) { $byN[$p['row']['n']] = $p; }
check('flip: the row becomes an expense', $byN[1]['row']['xt'] === 'expense' && $byN[1]['row']['dir'] === 'out' && $byN[1]['include']); check('swapdm: 2026-02-01 becomes 2026-01-02', $byN[2]['row']['date'] === '2026-01-02'); check('keep: the blocked duplicate reference is included again', $byN[4]['blocked'] === false && $byN[4]['include']); check('skip: excluded', $byN[5]['include'] === false); check('keep never rescues a row with an invalid amount', $byN[6]['blocked'] === true && $byN[6]['include'] === false);
$plN = import_plan($JW, $stF, import_default_choices($sF, $stF)); $byN0 = []; foreach ($plN as $p) { $byN0[$p['row']['n']] = $p; } check('without a fix the blocked rows stay out', $byN0[4]['blocked'] === true && $byN0[4]['include'] === false && $byN0[6]['include'] === false);
$report = import_json_report($stF); check('the report names rows, fields and reasons, and says what to send back', str_contains($report, 'IMPORT CHECK REPORT') && str_contains($report, 'transactions[3]') && str_contains($report, 'Same reference') && str_contains($report, 'COMPLETE corrected JSON') && strlen($report) < 4000); check('and lists errors before warnings', strpos($report, 'ERRORS') < strpos($report, 'WARNINGS'));
$cle = import_json_report(import_load_preview($JW, import_json_handle_text($JW, $jx(import_json_example()), 'ok.json'))['stmt']); check('a clean file reports no problems', str_contains($cle, 'No problems found'));
// the commit honours the fixes and writes only what is included
$chF['mode'] = 'reflect'; $resF = import_commit($JW, $tokF, $chF); eq($resF['imported'], 5, 'five rows imported (flip, swap, the kept duplicate, the other duplicate, wrong cat; skipped and broken stay out)');
$flipped = one('SELECT * FROM {transactions} WHERE user_id=? AND description=?', [$JW, 'Flip me']); eq([$flipped['type'], (int) $flipped['amount']], ['expense', 50000], 'the flipped row is stored as an expense of ₹500'); eq(one('SELECT date FROM {transactions} WHERE user_id=? AND description=?', [$JW, 'Swap me'])['date'], '2026-01-02', 'the swapped date is stored'); eq(val('SELECT category_id FROM {transactions} WHERE user_id=? AND description=?', [$JW, 'Wrong cat']), null, 'the category was cleared by its fix');
check('both rows with the same reference exist, the second one with a distinct key', (int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=? AND source=? AND source_ref LIKE ?', [$JW, 'json', 'D1%']) === 2);
$nBefore2 = (int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$JW]); $docA = $jDoc([$jTx(['ref' => 'AT1', 'amount' => '5']), $jTx(['ref' => 'AT2', 'amount' => '6'])]); $tokA2 = import_json_handle_text($JW, $jx($docA), 'atomic.json'); $GLOBALS['__import_fail_after_first_chunk'] = true;
try { import_commit($JW, $tokA2, import_default_choices(load_snapshot($JW), import_load_preview($JW, $tokA2)['stmt'])); } catch (Throwable $e) {} unset($GLOBALS['__import_fail_after_first_chunk']); eq((int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$JW]), $nBefore2, 'a failure in the middle of the commit writes nothing (all or nothing)'); check('and no half-created accounts or imports remain', !one('SELECT id FROM {imports} WHERE user_id=? AND filename=?', [$JW, 'atomic.json']));
// transfers between one account of yours mapped twice are refused with a clear message
$docT = $jDoc([$jTx(['type' => 'transfer', 'to_account' => 'Test Cash', 'amount' => '100'])]); $tokT = import_json_handle_text($JW, $jx($docT), 't.json'); $stT = import_load_preview($JW, $tokT)['stmt']; $chT = import_default_choices(load_snapshot($JW), $stT); $one = (int) load_snapshot($JW)['accounts'][0]['id']; $chT['acc'] = [$one, $one];
throws(fn() => import_commit($JW, $tokT, $chT), 'to itself', 'a transfer whose two accounts were mapped to the same account of yours is refused'); eq((int) one('SELECT COUNT(*) c FROM {transactions} WHERE user_id=? AND type=?', [$JW, 'transfer'])['c'], 0, 'nothing was written');

